"use strict";

const { existsSync } = require("node:fs");
const { createRequire } = require("node:module");
const { dirname, join } = require("node:path");

const PLUGIN_DIR = __dirname;
const SDK_DIR = join(
  PLUGIN_DIR,
  "..",
  "..",
  "..",
  "system-skills",
  "pier-canvas",
  "sdk"
);

const ALWAYS = {
  "pier/canvas": join(SDK_DIR, "index.d.ts"),
  "pier/host": join(SDK_DIR, "host.d.ts"),
};

function tryCreateRequire(from) {
  try {
    return createRequire(from);
  } catch {
    return null;
  }
}

function tsserverRequire() {
  const entry = process.argv.find((arg) =>
    /typescript[/\\]lib[/\\]tsserver/i.test(arg)
  );
  return (
    (entry ? tryCreateRequire(entry) : null) ??
    tryCreateRequire(join(process.cwd(), "package.json")) ??
    require
  );
}

function reactTypeFile(specifier) {
  const req = tsserverRequire();
  try {
    const dir = dirname(req.resolve("@types/react/package.json"));
    if (specifier === "react") {
      return join(dir, "index.d.ts");
    }
    if (specifier === "react/jsx-runtime") {
      return join(dir, "jsx-runtime.d.ts");
    }
    if (specifier === "react/jsx-dev-runtime") {
      return join(dir, "jsx-dev-runtime.d.ts");
    }
  } catch {
    return null;
  }
  return null;
}

function overridePath(specifier, hadResolved) {
  const always = ALWAYS[specifier];
  if (always && existsSync(always)) {
    return always;
  }
  if (hadResolved) {
    return null;
  }
  const react = reactTypeFile(specifier);
  return react && existsSync(react) ? react : null;
}

function dtsModule(ts, fileName) {
  return {
    resolvedModule: {
      extension: ts.Extension.Dts,
      isExternalLibraryImport: true,
      resolvedFileName: fileName,
    },
  };
}

function init(modules) {
  const ts = modules.typescript;
  return {
    create(info) {
      const host = info.languageServiceHost;
      const origLiterals = host.resolveModuleNameLiterals?.bind(host);
      const origNames = host.resolveModuleNames?.bind(host);

      host.resolveModuleNameLiterals = (
        literals,
        containingFile,
        redirectedReference,
        options,
        containingSourceFile,
        reusedNames
      ) => {
        const results = origLiterals
          ? origLiterals(
              literals,
              containingFile,
              redirectedReference,
              options,
              containingSourceFile,
              reusedNames
            )
          : literals.map((literal) =>
              ts.resolveModuleName(
                literal.text,
                containingFile,
                options,
                host,
                undefined,
                redirectedReference
              )
            );
        return results.map((resolved, index) => {
          const name = literals[index]?.text;
          if (!name) {
            return resolved;
          }
          const path = overridePath(name, Boolean(resolved?.resolvedModule));
          return path ? dtsModule(ts, path) : resolved;
        });
      };

      if (origNames) {
        host.resolveModuleNames = (
          moduleNames,
          containingFile,
          reusedNames,
          redirectedReference,
          options,
          containingSourceFile
        ) => {
          const results = origNames(
            moduleNames,
            containingFile,
            reusedNames,
            redirectedReference,
            options,
            containingSourceFile
          );
          return results.map((resolved, index) => {
            const name = moduleNames[index];
            const path = overridePath(name, Boolean(resolved));
            if (!path) {
              return resolved;
            }
            return {
              extension: ts.Extension.Dts,
              isExternalLibraryImport: true,
              resolvedFileName: path,
            };
          });
        };
      }

      return info.languageService;
    },
  };
}

init.overridePath = overridePath;
init.sdkDir = SDK_DIR;
module.exports = init;
